    "bodyEn": "### 1. Conceptual Framework & Samacheer Syllabus Overview\nMeaning, characteristics, advantages, and disadvantages of Sole Proprietorship. Unlimited liability concept. Suitability for small-scale local retail and services.\n\n### 2. Commercial Significance & Examination Focus\nUnderstanding this topic is essential for state board commerce examinations, clarifying both theoretical constructs and real-world commercial applications across Tamil Nadu and Indian markets.",
    "bodyTa": "### 1. பாடக் கருத்துக்களும் சமச்சீர் கல்வி விதிகளும்\nதனியாள் வணிகத்தின் பொருள், சிறப்பியல்புகள், நன்மைகள் மற்றும் குறைபாடுகள். வரையறாப் பொறுப்பு கருத்து. உள்ளூர் சில்லறை வணிகம் மற்றும் தனிநபர் சேவைகளுக்கு இதன் பொருத்தம்.\n\n### 2. தேர்வு வழிகாட்டுதலும் வணிக நடைமுறைகளும்\nவணிகவியல் தேர்வில் உயர் மதிப்பெண் பெற இப்பாடத்தின் அடிப்படைக் கருத்துக்கள் மற்றும் சட்டப்பிரிவுகள் மிக முக்கியமானவை.",
