        "questionTa": "கூட்டுப் பங்கு நிருமம் பாடத்தின் முக்கிய நடைமுறையை விளக்குக.",
        "solutionEn": "Joint Stock Company establishes standardized procedures ensuring economic efficiency and legal compliance.",
