    "svgContent": "<svg viewBox=\"0 0 800 400\" className=\"w-full h-auto\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect width=\"800\" height=\"400\" fill=\"#fefce8\" rx=\"12\" stroke=\"#fef08a\" strokeWidth=\"2\"/>\n  <rect x=\"30\" y=\"25\" width=\"740\" height=\"55\" rx=\"8\" fill=\"#d97706\"/>\n  <text x=\"400\" y=\"60\" fill=\"#ffffff\" fontSize=\"18\" fontWeight=\"bold\" textAnchor=\"middle\">Chapter 1: Historical Background of Commerce in the Sub-Continent</text>\n  <g transform=\"translate(50, 110)\">\n    <rect x=\"0\" y=\"0\" width=\"210\" height=\"110\" rx=\"10\" fill=\"#ffffff\" stroke=\"#d97706\" strokeWidth=\"2\"/>\n    <rect x=\"0\" y=\"0\" width=\"210\" height=\"30\" rx=\"10\" fill=\"#f59e0b\"/>\n    <text x=\"105\" y=\"20\" fill=\"#ffffff\" fontSize=\"12\" fontWeight=\"bold\" textAnchor=\"middle\">1. Principles &amp; Law</text>\n    <text x=\"105\" y=\"60\" fill=\"#1e293b\" fontSize=\"12\" textAnchor=\"middle\">Statutory Acts &amp; Codes</text>\n    <text x=\"105\" y=\"85\" fill=\"#64748b\" fontSize=\"11\" textAnchor=\"middle\">Samacheer Standards</text>\n\n    <rect x=\"245\" y=\"0\" width=\"210\" height=\"110\" rx=\"10\" fill=\"#ffffff\" stroke=\"#d97706\" strokeWidth=\"2\"/>\n    <rect x=\"245\" y=\"0\" width=\"210\" height=\"30\" rx=\"10\" fill=\"#f59e0b\"/>\n    <text x=\"350\" y=\"20\" fill=\"#ffffff\" fontSize=\"12\" fontWeight=\"bold\" textAnchor=\"middle\">2. Market Operations</text>\n    <text x=\"350\" y=\"60\" fill=\"#1e293b\" fontSize=\"12\" textAnchor=\"middle\">Channels &amp; Intermediaries</text>\n    <text x=\"350\" y=\"85\" fill=\"#64748b\" fontSize=\"11\" textAnchor=\"middle\">Banking &amp; Logistics</text>\n\n    <rect x=\"490\" y=\"0\" width=\"210\" height=\"110\" rx=\"10\" fill=\"#ffffff\" stroke=\"#d97706\" strokeWidth=\"2\"/>\n    <rect x=\"490\" y=\"0\" width=\"210\" height=\"30\" rx=\"10\" fill=\"#f59e0b\"/>\n    <text x=\"595\" y=\"20\" fill=\"#ffffff\" fontSize=\"12\" fontWeight=\"bold\" textAnchor=\"middle\">3. Economic Impact</text>\n    <text x=\"595\" y=\"60\" fill=\"#1e293b\" fontSize=\"12\" textAnchor=\"middle\">Wealth &amp; Employment</text>\n    <text x=\"595\" y=\"85\" fill=\"#64748b\" fontSize=\"11\" textAnchor=\"middle\">Sustainable Growth</text>\n  </g>\n  <g transform=\"translate(50, 250)\">\n    <rect x=\"0\" y=\"0\" width=\"700\" height=\"115\" rx=\"8\" fill=\"#ffffff\" stroke=\"#e2e8f0\" strokeWidth=\"1.5\"/>\n    <text x=\"25\" y=\"32\" fill=\"#b45309\" fontSize=\"13\" fontWeight=\"bold\">Commercial Framework Highlights:</text>\n    <text x=\"25\" y=\"62\" fill=\"#334155\" fontSize=\"12\">• Regulated by Indian commercial statutes (Contract Act 1872, Companies Act 2013, GST Acts).</text>\n    <text x=\"25\" y=\"88\" fill=\"#334155\" fontSize=\"12\">• Integrates domestic distribution networks with global financial markets.</text>\n  </g>\n</svg>",
